  1	import {createHash} from "node:crypto";
  2	
  3	import {businessDayAccrual, diPercentAccrual} from "@offroad/financial-core";
  4	import Decimal from "decimal.js";
  5	import {z} from "zod";
  6	
  7	/**
  8	 * Executor of the method `build-interest-and-indexation-schedule` (v4, after the third independent
  9	 * review). Projects each series period by period with the factors its indenture writes: an annual
 10	 * rate accrues exponentially over business days of a 252-day year; a DI series compounds the DI
 11	 * factor with the spread factor; a "p% of DI" series compounds p times the daily DI; an IPCA series
 12	 * updates its nominal at each anniversary by the monthly index of the lagged month and accrues the
 13	 * spread on the updated nominal. A coupon is paid on its date: the accrual is split at the payment,
 14	 * what accrued before is paid, what accrues after is carried. The opening principal is a nominal
 15	 * (unit value times quantity, updated where the base holds the update); a ledger balance that
 16	 * includes accrued interest and costs is not a principal and names a gap. The accrued remuneration
 17	 * at the reference date comes from the base or the first coupon is declared incomplete. Rounding
 18	 * follows what each indenture writes, layer by layer (DI factor, spread factor, their product, the
 19	 * daily accumulation, the amount). The IPCA update between anniversaries is pro rata by business
 20	 * days (dup/dut) when the base gives the counts, and declared as not projected otherwise. When the
 21	 * base does not say whether the IPCA update is capitalized or paid, both treatments are projected as
 22	 * scenarios. Nothing missing becomes zero: an absent amortization schedule leaves the principal
 23	 * projection insufficient in every aggregate, and the projected total is compared to the ledger's
 24	 * control so omitted series are named. The unit is anchored to the source that states it; coupon
 25	 * positions inside a period must advance.
 26	 */
 27	const nonNegative = z.string().regex(/^\d+(\.\d+)?$/);
 28	const rate = z.string().regex(/^-?\d+(\.\d+)?$/);
 29	const nonEmpty = z.string().trim().min(1);
 30	const isoDate = z.string().regex(/^\d{4}-\d{2}-\d{2}$/);
 31	const isoMonth = z.string().regex(/^\d{4}-\d{2}$/);
 32	const unitSchema = z.enum(["BRL", "BRL thousand", "BRL million", "USD", "USD thousand"]);
 33	const anchorSchema = z.object({document: nonEmpty, page: z.number().int().positive().optional(), note: nonEmpty.optional(), clause: nonEmpty.optional()}).strict();
 34	type Anchor = z.infer<typeof anchorSchema>;
 35	const compare = (a: string, b: string) => (a < b ? -1 : a > b ? 1 : 0);
 36	
 37	export const projectionPeriodSchema = z.object({
 38	  id: nonEmpty,
 39	  start: isoDate,
 40	  end: isoDate,
 41	  /** Business days of the period, from the calendar the base cites (holidays included). */
 42	  businessDays: z.number().int().nonnegative(),
 43	  /** The calendar the count comes from. */
 44	  anchor: anchorSchema,
 45	}).strict();
 46	
 47	export const curveSchema = z.object({
 48	  id: nonEmpty,
 49	  kind: z.enum(["CDI", "IPCA"]),
 50	  /** Annual effective rate per period as a decimal, or the daily rate the source publishes (annualized by the executor as (1 + daily)^252 - 1). One of the two. */
 51	  annualRateByPeriod: z.record(nonEmpty, rate).nullable().default(null),
 52	  dailyRateByPeriod: z.record(nonEmpty, rate).nullable().default(null),
 53	  /** IPCA only: monthly variation by calendar month (YYYY-MM) as a decimal, for the anniversary updates. */
 54	  monthlyRateByMonth: z.record(isoMonth, rate).nullable().default(null),
 55	  source: z.object({title: nonEmpty, url: z.string().optional(), asOf: isoDate, anchor: anchorSchema}).strict(),
 56	}).strict();
 57	
 58	export const seriesRemunerationSchema = z.discriminatedUnion("type", [
 59	  z.object({type: z.literal("spread_over_index"), spreadPerYear: rate}).strict(),
 60	  z.object({type: z.literal("percent_of_index"), percentOfIndex: nonNegative}).strict(),
 61	  z.object({type: z.literal("fixed"), ratePerYear: rate}).strict(),
 62	]);
 63	
 64	/** Rounding the indenture writes, layer by layer: the index factor, the spread factor, their product (Fator Juros), the daily accumulation and the amount. */
 65	const layerSchema = z.object({decimals: z.number().int().min(2).max(16), mode: z.enum(["round", "truncate"])}).strict();
 66	export const roundingSchema = z.object({
 67	  indexFactor: layerSchema,
 68	  spreadFactor: layerSchema,
 69	  interestFactor: layerSchema,
 70	  dailyAccumulation: layerSchema,
 71	  amount: layerSchema,
 72	  anchor: anchorSchema,
 73	}).strict();
 74	
 75	export const seriesInputSchema = z.object({
 76	  id: nonEmpty,
 77	  label: nonEmpty,
 78	  /** The nominal at the reference date and where it comes from; a ledger balance including accrued interest is not a nominal. */
 79	  openingPrincipal: z.object({value: nonNegative, basis: z.enum(["unit_value_x_quantity", "unit_value_x_quantity_updated", "trustee_report_nominal", "ledger_balance_including_accrued"]), anchor: anchorSchema}).strict(),
 80	  /** Remuneration accrued at the reference date since the last payment; null when the base does not hold it. */
 81	  openingAccrued: z.object({value: nonNegative, anchor: anchorSchema}).strict().nullable(),
 82	  indexer: z.enum(["CDI", "IPCA", "fixed", "unknown"]),
 83	  remuneration: seriesRemunerationSchema.nullable(),
 84	  /** Coupon payment dates with the business days from the start of the period that holds them, from the calendar the base cites; positions inside a period must advance. */
 85	  couponDates: z.array(z.object({date: isoDate, businessDaysFromPeriodStart: z.number().int().nonnegative()}).strict()).nullable(),
 86	  /** Scheduled principal payments; null when the base has no amortization schedule for the series. */
 87	  amortization: z.array(z.object({date: isoDate, amount: nonNegative}).strict()).nullable(),
 88	  /** IPCA only: how the update is treated (capitalized or paid); null when the indenture is not in the base, in which case both are projected. */
 89	  indexationTreatment: z.enum(["capitalized_principal", "cash_paid"]).nullable(),
 90	  /** IPCA only: the anniversary day and the lag in months the indenture writes for the index number, and, per period, the business days elapsed since the last anniversary (dup) over the business days of that anniversary month (dut) for the pro rata at the period end; null when the base does not give the counts. */
 91	  indexation: z.object({anniversaryDay: z.number().int().min(1).max(31), lagMonths: z.number().int().min(0).max(3), proRataByPeriod: z.record(nonEmpty, z.object({dup: z.number().int().nonnegative(), dut: z.number().int().positive()}).strict()).nullable(), anchor: anchorSchema}).strict().nullable(),
 92	  rounding: roundingSchema.nullable(),
 93	  curveId: nonEmpty.nullable(),
 94	  anchors: z.object({balance: anchorSchema, terms: anchorSchema.nullable(), payments: anchorSchema.nullable(), amortization: anchorSchema.nullable()}).strict(),
 95	}).strict();
 96	
 97	const UNIT_WORDS: Record<z.infer<typeof unitSchema>, RegExp> = {"BRL": /\b(R\$|reais|BRL)\b(?!\s*(mil|milh))/i, "BRL thousand": /\b(mil|thousand)\b/i, "BRL million": /\b(milh[õo]es|million)\b/i, "USD": /\bUSD\b(?!\s*(mil|thousand))/i, "USD thousand": /\bUSD\b.*\b(mil|thousand)\b/i};
 98	
 99	export const interestScheduleInputSchema = z.object({
100	  referenceDate: isoDate,
101	  unit: unitSchema,
102	  /** Where the source states the unit; its note must name it, so a relabelled scale is refused. */
103	  unitAnchor: anchorSchema.extend({note: nonEmpty}),
104	  periods: z.array(projectionPeriodSchema).min(1),
105	  curves: z.array(curveSchema).default([]),
106	  series: z.array(seriesInputSchema).min(1),
107	  /** The ledger's control: the series it holds and their nominal total, so omitted series are named and the projection's coverage is measured. */
108	  ledgerControl: z.object({seriesIds: z.array(nonEmpty), grossDebt: nonNegative, anchor: anchorSchema}).strict().nullable().default(null),
109	  /** The finance expense of the last closed period, to bridge against; null when not in the base. */
110	  accountingInterestLastPeriod: z.object({value: z.string().regex(/^-?\d+(\.\d+)?$/), periodId: nonEmpty, anchor: anchorSchema}).strict().nullable().default(null),
111	}).strict().superRefine((input, context) => {
112	  if (!UNIT_WORDS[input.unit].test(input.unitAnchor.note)) context.addIssue({code: "custom", path: ["unitAnchor"], message: `the unit anchor's note does not name the unit ${input.unit}; a relabelled scale is refused`});
113	  const periodIds = new Set<string>();
114	  const sorted = [...input.periods].sort((a, b) => compare(a.start, b.start));
115	  sorted.forEach((period, index) => {
116	    if (periodIds.has(period.id)) context.addIssue({code: "custom", path: ["periods"], message: `duplicate period ${period.id}`});
117	    periodIds.add(period.id);
118	    if (period.end <= period.start) context.addIssue({code: "custom", path: ["periods", index], message: `period ${period.id} ends before it starts`});
119	    if (index > 0 && sorted[index - 1]!.end !== period.start) context.addIssue({code: "custom", path: ["periods", index], message: `period ${period.id} does not start where ${sorted[index - 1]!.id} ends`});
120	  });
121	  if (sorted[0] && sorted[0].start !== input.referenceDate) context.addIssue({code: "custom", path: ["periods", 0], message: "the first period must start at the reference date"});
122	  const curveIds = new Set<string>();
123	  input.curves.forEach((curve, index) => {
124	    if (curveIds.has(curve.id)) context.addIssue({code: "custom", path: ["curves"], message: `duplicate curve ${curve.id}`});
125	    curveIds.add(curve.id);
126	    if ((curve.annualRateByPeriod === null) === (curve.dailyRateByPeriod === null)) context.addIssue({code: "custom", path: ["curves", index], message: `curve ${curve.id} must carry exactly one of annualRateByPeriod and dailyRateByPeriod`});
127	    if (curve.kind !== "IPCA" && curve.monthlyRateByMonth !== null) context.addIssue({code: "custom", path: ["curves", index], message: `curve ${curve.id} is not IPCA and carries monthly index variations`});
128	  });
129	  const seriesIds = new Set<string>();
130	  input.series.forEach((series, index) => {
131	    if (seriesIds.has(series.id)) context.addIssue({code: "custom", path: ["series"], message: `duplicate series ${series.id}`});
132	    seriesIds.add(series.id);
133	    const dates = new Set<string>();
134	    const lastPosition = new Map<string, number>();
135	    for (const coupon of [...(series.couponDates ?? [])].sort((a, b) => compare(a.date, b.date))) {
136	      if (dates.has(coupon.date)) context.addIssue({code: "custom", path: ["series", index, "couponDates"], message: `${series.id}: coupon date ${coupon.date} listed twice`});
137	      dates.add(coupon.date);
138	      const period = sorted.find((entry) => coupon.date > entry.start && coupon.date <= entry.end);
139	      if (period && coupon.businessDaysFromPeriodStart > period.businessDays) context.addIssue({code: "custom", path: ["series", index, "couponDates"], message: `${series.id}: coupon ${coupon.date} claims ${coupon.businessDaysFromPeriodStart} business days inside ${period.id}, which has ${period.businessDays}`});
140	      if (period) {
141	        const previous = lastPosition.get(period.id);
142	        if (previous !== undefined && coupon.businessDaysFromPeriodStart <= previous) context.addIssue({code: "custom", path: ["series", index, "couponDates"], message: `${series.id}: coupon ${coupon.date} sits at ${coupon.businessDaysFromPeriodStart} business days, not after the previous coupon of ${period.id} at ${previous}; positions inside a period must advance`});
143	        lastPosition.set(period.id, coupon.businessDaysFromPeriodStart);
144	      }
145	    }
146	    if (series.indexation?.proRataByPeriod) for (const [periodId, counts] of Object.entries(series.indexation.proRataByPeriod)) { if (!periodIds.has(periodId)) context.addIssue({code: "custom", path: ["series", index, "indexation"], message: `${series.id}: pro rata names a period that is not projected: ${periodId}`}); if (counts.dup > counts.dut) context.addIssue({code: "custom", path: ["series", index, "indexation"], message: `${series.id}: dup ${counts.dup} exceeds dut ${counts.dut} in ${periodId}`}); }
147	    if (series.indexer !== "IPCA" && (series.indexationTreatment !== null || series.indexation !== null)) context.addIssue({code: "custom", path: ["series", index], message: `${series.id}: indexation fields belong to IPCA series only`});
148	  });
149	});
150	export type InterestScheduleInput = z.input<typeof interestScheduleInputSchema>;
151	
152	type Calculation = {id: string; formula: string; operands: Record<string, string>; result: string; unit: string};
153	type Row = {
154	  period: string; opening_principal: string; indexation_factor: string; indexation_accrued: string; indexation_capitalized: string; indexation_paid: string;
155	  coupon_factor: string; coupon_accrued: string; coupon_paid: string; coupon_carried: string; principal_paid: string | null; closing_principal: string; calendar_anchor: Anchor;
156	};
157	type Totals = {cash_interest: string; cash_indexation: string; indexation_capitalized: string; principal_paid: string | null};
158	type SeriesSchedule = {
159	  series_id: string; label: string; indexer: string; remuneration: string;
160	  opening_principal: {value: string; basis: string; anchor: Anchor};
161	  opening_accrued: {value: string; anchor: Anchor} | null;
162	  first_coupon_complete: boolean;
163	  curve: {id: string; asOf: string; title: string; anchor: Anchor} | null;
164	  rounding: {indexFactor: {decimals: number; mode: string}; spreadFactor: {decimals: number; mode: string}; interestFactor: {decimals: number; mode: string}; dailyAccumulation: {decimals: number; mode: string}; amount: {decimals: number; mode: string}; anchor: Anchor} | null;
165	  principal_projection: "scheduled" | "insufficient_evidence";
166	  treatment: "capitalized_principal" | "cash_paid" | "not_indexed";
167	  /** Present only when the base does not say how the IPCA update is treated: both projections, side by side. */
168	  treatment_scenarios: Array<{treatment: "capitalized_principal" | "cash_paid"; rows: Row[]; totals: Totals}> | null;
169	  rows: Row[];
170	  totals: Totals;
171	  anchors: {balance: Anchor; terms: Anchor | null; payments: Anchor | null; amortization: Anchor | null; indexation: Anchor | null};
172	};
173	
174	export type InterestScheduleOutput = {
175	  schema_version: "method.build-interest-and-indexation-schedule.v4";
176	  reference_date: string;
177	  unit: string;
178	  state: "complete" | "partial" | "blocked";
179	  block_reasons: string[];
180	  assumptions: string[];
181	  schedule_by_series: SeriesSchedule[];
182	  schedule_aggregate: {
183	    by_period: Array<{period: string; cash_interest: string; cash_indexation: string; indexation_capitalized: string; principal_paid: string | null; closing_principal: string | null}>;
184	    by_indexer: Array<{indexer: string; cash_interest: string; cash_indexation: string; indexation_capitalized: string; closing_principal: string | null; series: string[]}>;
185	    opening_principal_projected: string;
186	    principal_projection_complete: boolean;
187	    treatment_scenarios_pending: string[];
188	  } | null;
189	  ledger_coverage: {projected: string; ledger: string; share: string; series_omitted: string[]; anchor: Anchor} | null;
190	  accounting_bridge: {projected: string | null; accounting: string; difference: string | null; period: string; anchor: Anchor; state: "compared" | "insufficient_evidence"; reason: string | null} | null;
191	  uncovered_series: Array<{series_id: string; reason: string; state: "insufficient_evidence"}>;
192	  trace: {calculations: Calculation[]; inputFingerprint: string; outputFingerprint: string};
193	};
194	
195	const d = (value: Decimal.Value) => new Decimal(value);
196	const out = (value: Decimal) => value.toDecimalPlaces(8).toFixed();
197	const stableStringify = (value: unknown): string => JSON.stringify(value, (_key, inner: unknown) => (inner && typeof inner === "object" && !Array.isArray(inner) ? Object.fromEntries(Object.entries(inner as Record<string, unknown>).sort(([a], [b]) => compare(a, b))) : inner));
198	const fingerprint = (value: unknown) => createHash("sha256").update(stableStringify(value)).digest("hex");
199	const sortRecord = <T,>(record: Record<string, T> | null) => (record ? Object.fromEntries(Object.entries(record).sort(([a], [b]) => compare(a, b))) : null);
200	
201	function canonical(input: z.infer<typeof interestScheduleInputSchema>) {
202	  return {
203	    ...input,
204	    periods: [...input.periods].sort((a, b) => compare(a.start, b.start)),
205	    curves: [...input.curves].sort((a, b) => compare(a.id, b.id)).map((curve) => ({...curve, annualRateByPeriod: sortRecord(curve.annualRateByPeriod), dailyRateByPeriod: sortRecord(curve.dailyRateByPeriod), monthlyRateByMonth: sortRecord(curve.monthlyRateByMonth)})),
206	    series: [...input.series].sort((a, b) => compare(a.id, b.id)).map((series) => ({...series, couponDates: series.couponDates ? [...series.couponDates].sort((a, b) => compare(a.date, b.date)) : null, amortization: series.amortization ? [...series.amortization].sort((a, b) => compare(a.date, b.date) || compare(a.amount, b.amount)) : null, indexation: series.indexation ? {...series.indexation, proRataByPeriod: sortRecord(series.indexation.proRataByPeriod)} : null})),
207	    ledgerControl: input.ledgerControl ? {...input.ledgerControl, seriesIds: [...input.ledgerControl.seriesIds].sort(compare)} : null,
208	  };
209	}
210	
211	const describeRemuneration = (series: z.infer<typeof seriesInputSchema>) => {
212	  const remuneration = series.remuneration!;
213	  if (remuneration.type === "fixed") return `fixed ${remuneration.ratePerYear} per year`;
214	  if (remuneration.type === "percent_of_index") return `${remuneration.percentOfIndex} of ${series.indexer}`;
215	  return `${series.indexer} + ${remuneration.spreadPerYear} per year`;
216	};
217	const addMonths = (isoMonth: string, months: number) => { const [year, month] = isoMonth.split("-").map(Number) as [number, number]; const index = year * 12 + (month - 1) + months; return `${Math.floor(index / 12)}-${String((index % 12) + 1).padStart(2, "0")}`; };
218	/** Anniversary dates strictly after `start` and up to `end`, on the series' anniversary day (month-end clipped). */
219	function anniversaries(start: string, end: string, day: number): string[] {
220	  const dates: string[] = [];
221	  let month = start.slice(0, 7);
222	  for (let guard = 0; guard < 120; guard += 1) {
223	    const [year, monthNumber] = month.split("-").map(Number) as [number, number];
224	    const lastDay = new Date(Date.UTC(year, monthNumber, 0)).getUTCDate();
225	    const date = `${month}-${String(Math.min(day, lastDay)).padStart(2, "0")}`;
226	    if (date > end) break;
227	    if (date > start) dates.push(date);
228	    month = addMonths(month, 1);
229	  }
230	  return dates;
231	}
232	
233	export function buildInterestAndIndexationSchedule(raw: InterestScheduleInput): InterestScheduleOutput {
234	  const input = canonical(interestScheduleInputSchema.parse(raw));
235	  const calculations: Calculation[] = [];
236	  const record = (calculation: Omit<Calculation, "unit">, unit: string = input.unit) => calculations.push({...calculation, unit});
237	  const curves = new Map(input.curves.map((curve) => [curve.id, curve]));
238	  const uncovered: InterestScheduleOutput["uncovered_series"] = [];
239	  const assumptions = new Set<string>();
240	  const blockReasons: string[] = [];
241	  const schedules: SeriesSchedule[] = [];
242	
243	  /** Annual rate of a curve for a period: as published, or annualized from the daily rate the source publishes. */
244	  const annualRate = (curve: z.infer<typeof curveSchema>, periodId: string): string | null => {
245	    if (curve.annualRateByPeriod) return curve.annualRateByPeriod[periodId] ?? null;
246	    const daily = curve.dailyRateByPeriod?.[periodId];
247	    if (daily === undefined) return null;
248	    const annual = d(daily).plus(1).pow(252).minus(1);
249	    record({id: `financial.daily_rate_annualized:${curve.id}:${periodId}`, formula: "(1 + dailyRate)^252 - 1", operands: {dailyRate: daily}, result: out(annual)}, "x");
250	    return out(annual);
251	  };
252	
253	  for (const series of input.series) {
254	    if (series.openingPrincipal.basis === "ledger_balance_including_accrued") { uncovered.push({series_id: series.id, reason: `the opening figure of ${series.label} is a ledger balance that includes accrued interest, monetary variation and transaction costs; the nominal (unit value times quantity, updated where indexed) is not in the base`, state: "insufficient_evidence"}); continue; }
255	    if (series.indexer === "unknown" || series.remuneration === null) { uncovered.push({series_id: series.id, reason: `no source in the base states the indexer or the remuneration of ${series.label}`, state: "insufficient_evidence"}); continue; }
256	    if (!series.anchors.terms) { uncovered.push({series_id: series.id, reason: `the terms of ${series.label} carry no anchor; a term without a source is not a term`, state: "insufficient_evidence"}); continue; }
257	    if (series.couponDates === null || !series.anchors.payments) { uncovered.push({series_id: series.id, reason: `the payment dates of ${series.label} are not in the base; coupons cannot be placed in time`, state: "insufficient_evidence"}); continue; }
258	    if ((series.indexer === "CDI" && series.remuneration.type === "fixed") || (series.indexer === "fixed" && series.remuneration.type !== "fixed") || (series.indexer === "IPCA" && series.remuneration.type !== "spread_over_index")) {
259	      uncovered.push({series_id: series.id, reason: `the remuneration type of ${series.label} (${series.remuneration.type}) does not match its indexer (${series.indexer})`, state: "insufficient_evidence"}); continue;
260	    }

261	    const curve = series.curveId ? curves.get(series.curveId) ?? null : null;
262	    if (series.indexer !== "fixed") {
263	      if (!curve) { uncovered.push({series_id: series.id, reason: `no registered curve for the ${series.indexer} of ${series.label}; a curve without source and date does not enter`, state: "insufficient_evidence"}); continue; }
264	      if (curve.kind !== series.indexer) { uncovered.push({series_id: series.id, reason: `curve ${curve.id} is a ${curve.kind} curve and ${series.label} is indexed to ${series.indexer}`, state: "insufficient_evidence"}); continue; }
265	      if (series.indexer === "CDI" && input.periods.some((period) => annualRate(curve, period.id) === null)) { uncovered.push({series_id: series.id, reason: `curve ${curve.id} does not cover every projected period`, state: "insufficient_evidence"}); continue; }
266	      if (curve.source.asOf !== input.referenceDate) assumptions.add(`curve ${curve.id} is dated ${curve.source.asOf}, not the reference date ${input.referenceDate}: the projection uses it as the base scenario and does not call it the curve of the reference date`);
267	    }
268	    if (series.indexer === "IPCA") {
269	      if (!series.indexation) { uncovered.push({series_id: series.id, reason: `the anniversary day and the index lag of ${series.label} are not in the base; the monthly update cannot be placed`, state: "insufficient_evidence"}); continue; }
270	      if (!curve!.monthlyRateByMonth) { uncovered.push({series_id: series.id, reason: `curve ${curve!.id} carries no monthly index variations; the IPCA update of ${series.label} needs them`, state: "insufficient_evidence"}); continue; }
271	      const needed = input.periods.flatMap((period) => anniversaries(period.start, period.end, series.indexation!.anniversaryDay)).map((date) => addMonths(date.slice(0, 7), -series.indexation!.lagMonths));
272	      const missing = needed.filter((month) => curve!.monthlyRateByMonth![month] === undefined);
273	      if (missing.length > 0) { uncovered.push({series_id: series.id, reason: `curve ${curve!.id} lacks the monthly variation of ${[...new Set(missing)].join(", ")} that the anniversaries of ${series.label} need`, state: "insufficient_evidence"}); continue; }
274	      if (!series.indexation.proRataByPeriod) assumptions.add(`${series.id}: IPCA updates are applied at each anniversary with the monthly variation of the lagged month; the pro rata between the last anniversary and the period end (dup/dut) is not projected because the base gives no business-day counts (declared approximation)`);
275	      else if (input.periods.some((period) => series.indexation!.proRataByPeriod![period.id] === undefined)) { uncovered.push({series_id: series.id, reason: `the pro rata counts (dup/dut) of ${series.label} are missing for ${input.periods.filter((period) => series.indexation!.proRataByPeriod![period.id] === undefined).map((period) => period.id).join(", ")}`, state: "insufficient_evidence"}); continue; }
276	      if (series.indexationTreatment === null) assumptions.add(`${series.id}: the base does not say whether the IPCA update is capitalized or paid; both treatments are projected as scenarios and neither is chosen`);
277	    }
278	    if (!series.openingAccrued) assumptions.add(`${series.id}: the remuneration accrued at ${input.referenceDate} is not in the base; the first coupon is declared incomplete and carries only what accrues from the reference date`);
279	    const principalProjection: "scheduled" | "insufficient_evidence" = series.amortization && series.anchors.amortization ? "scheduled" : "insufficient_evidence";
280	    const rounding = series.rounding;
