  5	/**
  6	 * Test helper: the top-level keys an executor emits must be exactly the Outputs the method declares.
  7	 * The compiled skill schema is closed over those Outputs, so an undeclared key would be rejected at
  8	 * runtime and a missing required key would fail validation.
  9	 */
 10	const here = dirname(fileURLToPath(import.meta.url));
 11	
 12	export function declaredOutputs(methodPath: string): {required: string[]; optional: string[]} {
 13	  const text = readFileSync(resolve(here, "../../knowledge/procedures", methodPath), "utf8");
 14	  const section = text.split(/^# Outputs\n/m)[1]?.split(/^# /m)[0] ?? "";
 15	  const required: string[] = [];
 16	  const optional: string[] = [];
 17	  for (const line of section.split("\n")) {
 18	    const match = /^- ([a-z][a-z0-9_.-]*) \(([a-z_]+), (required|optional)\)/.exec(line);
 19	    if (!match) continue;
 20	    (match[3] === "required" ? required : optional).push(match[1]!);
 21	  }
 22	  return {required, optional};
 23	}
 24	
 25	export function contractMismatch(output: Record<string, unknown>, methodPath: string): string[] {
 26	  const {required, optional} = declaredOutputs(methodPath);
 27	  const declared = new Set([...required, ...optional]);
 28	  const keys = Object.keys(output);
 29	  const problems: string[] = [];
 30	  for (const key of keys) if (!declared.has(key)) problems.push(`emitted key ${key} is not declared in the method's Outputs`);
 31	  for (const key of required) if (!(key in output)) problems.push(`required output ${key} is missing`);
 32	  return problems;
 33	}

