/bin/bash -lc "node <<'NODE'
const Decimal=require('decimal.js'); Decimal.set({precision:80}); const d=x=>new Decimal(x);
const round=(x,n)=>d(x).toDecimalPlaces(n,Decimal.ROUND_HALF_UP);
const trunc=(x,n)=>d(x).toDecimalPlaces(n,Decimal.ROUND_DOWN);
const out=x=>d(x).toDecimalPlaces(8,Decimal.ROUND_HALF_UP).toFixed();
const daily='0.0005166'; const annual=d(1).plus(daily).pow(252).minus(1); console.log('annual raw',annual.toFixed(20),'annual out',out(annual));
const annualUsed=out(annual);
function business(rate,days){return d(1).plus(rate).pow(d(days).div(252)).minus(1)}
function diSpread(days){const fi=round(business(annualUsed,days),8), fs=round(business('0.0065',days),9); return round(fi.plus(1).times(fs.plus(1)).minus(1),9)}
function diPct(days){const dailyDi=d(1).plus(annualUsed).pow(d(1).div(252)).minus(1); const a=d(1).plus(dailyDi.times('1.04')).pow(days).minus(1); return round(trunc(a,16),9)}
function fixed(days){return round(round(business('0.1415',days),9),9)}
function project(id,principal,factor,pays){let carried=d(0), ci=d(0); const rows=[]; for(let p=0;p<4;p++){let used=0, paid=d(0), accrued=d(0), pf=d(1); const entries=pays[p]||[]; for(let i=0;i<entries.length;i++){const pos=entries[i], days=pos-used, f=factor(days), a=trunc(d(principal).plus(carried).times(f),8); accrued=accrued.plus(a); carried=carried.plus(a); paid=paid.plus(carried); carried=d(0); used=pos; pf=pf.times(f.plus(1)); if(i===entries.length-1){const rest=63-used, fr=factor(rest), ar=trunc(d(principal).times(fr),8); accrued=accrued.plus(ar); carried=carried.plus(ar); pf=pf.times(fr.plus(1));}}
if("'!entries.length){const f=factor(63), a=trunc(d(principal).plus(carried).times(f),8); accrued=a; carried=carried.plus(a); pf=f.plus(1)} ci=ci.plus(paid); rows.push({p:p+1,factor:out(pf.minus(1)),accrued:out(accrued),paid:out(paid),carried:out(carried)});} return {id,principal,rows,total:out(ci)}}
const a=project('"'deb-13-1','304160',diSpread,{1:[53],3:[52]});
const b=project('deb-14-1','411643',diPct,{0:[9],2:[10]});
const c=project('deb-15-2','406349',fixed,{1:[53],3:[52]});
console.log(JSON.stringify([a,b,c],null,2));
for(let p=0;p<4;p++) console.log('aggregate p'+(p+1),out(d(a.rows[p].paid).plus(b.rows[p].paid).plus(c.rows[p].paid)));
console.log('by CDI cash',out(d(a.total).plus(b.total)),'fixed',c.total,'projected',d(a.principal).plus(b.principal).plus(c.principal).toFixed(),'share',out(d('1122152').div('5670186')),'CDI closing',d(a.principal).plus(b.principal).toFixed());
NODE"

